CREATE TABLE "AlertSettings" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"lowThreshold" DOUBLE PRECISION NOT NULL DEFAULT 70,"highThreshold" DOUBLE PRECISION NOT NULL DEFAULT 180,"alertsEnabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AlertSettings_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "AlertSettings_userId_key" ON "AlertSettings"("userId");ALTER TABLE "AlertSettings" ADD CONSTRAINT "AlertSettings_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;